CREATE TABLE "TimePeriod" ("id" TEXT NOT NULL, "schoolId" TEXT NOT NULL, "name" TEXT NOT NULL, "startTime" TEXT NOT NULL, "endTime" TEXT NOT NULL, "sortOrder" INTEGER NOT NULL, "isBreak" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "TimePeriod_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "TimePeriod_schoolId_sortOrder_key" ON "TimePeriod"("schoolId", "sortOrder"); CREATE UNIQUE INDEX "TimePeriod_schoolId_name_key" ON "TimePeriod"("schoolId", "name"); ALTER TABLE "TimePeriod" ADD CONSTRAINT "TimePeriod_schoolId_fkey" FOREIGN KEY ("schoolId") REFERENCES "School"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "TimetableEntry" ("id" TEXT NOT NULL, "schoolId" TEXT NOT NULL, "academicYearId" TEXT NOT NULL, "classId" TEXT NOT NULL, "sectionId" TEXT NOT NULL, "subjectId" TEXT NOT NULL, "teacherId" TEXT NOT NULL, "periodId" TEXT NOT NULL, "weekday" INTEGER NOT NULL, "room" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "TimetableEntry_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "TimetableEntry_academicYearId_sectionId_weekday_periodId_key" ON "TimetableEntry"("academicYearId", "sectionId", "weekday", "periodId"); CREATE UNIQUE INDEX "TimetableEntry_academicYearId_teacherId_weekday_periodId_key" ON "TimetableEntry"("academicYearId", "teacherId", "weekday", "periodId"); CREATE INDEX "TimetableEntry_schoolId_academicYearId_classId_sectionId_idx" ON "TimetableEntry"("schoolId", "academicYearId", "classId", "sectionId");
ALTER TABLE "TimetableEntry" ADD CONSTRAINT "TimetableEntry_schoolId_fkey" FOREIGN KEY ("schoolId") REFERENCES "School"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "TimetableEntry" ADD CONSTRAINT "TimetableEntry_academicYearId_fkey" FOREIGN KEY ("academicYearId") REFERENCES "AcademicYear"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "TimetableEntry" ADD CONSTRAINT "TimetableEntry_classId_fkey" FOREIGN KEY ("classId") REFERENCES "SchoolClass"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "TimetableEntry" ADD CONSTRAINT "TimetableEntry_sectionId_fkey" FOREIGN KEY ("sectionId") REFERENCES "Section"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "TimetableEntry" ADD CONSTRAINT "TimetableEntry_subjectId_fkey" FOREIGN KEY ("subjectId") REFERENCES "Subject"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "TimetableEntry" ADD CONSTRAINT "TimetableEntry_teacherId_fkey" FOREIGN KEY ("teacherId") REFERENCES "Teacher"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "TimetableEntry" ADD CONSTRAINT "TimetableEntry_periodId_fkey" FOREIGN KEY ("periodId") REFERENCES "TimePeriod"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
